import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const i="/llamatron/assets/euclid_editor.B4nP24bf.svg",u=JSON.parse('{"title":"Euclid","description":"","frontmatter":{},"headers":[],"relativePath":"generators/EUCLID.md","filePath":"generators/EUCLID.md"}'),n={name:"generators/EUCLID.md"};function o(h,t,d,l,c,p){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="euclid" tabindex="-1">Euclid <a class="header-anchor" href="#euclid" aria-label="Permalink to &quot;Euclid&quot;">​</a></h1><p>A Euclidean rhythm spreads a number of hits as evenly as it can over a number of steps: three over eight is X . . X . . X ., the Cuban tresillo, and the same sum gives traditional rhythms the world over. A Euclidean mask keeps only the notes of a clip that start on a hit, the rest falling silent, so you can write a full pattern, a note on every step, and carve rhythms out of it.</p><p>A mask can be set in the track editor&#39;s <code>+ Euclid</code> section, for every clip on the track, and as a Euclid generator painted on clips through a chain. Masks stack: a note plays only where every mask has a hit.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+i+'" alt="A Euclid generator&#39;s settings, its rhythm drawn under them"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Hits</td><td>How many hits, from 1 to 32. A mask with no hits masks nothing. <code>H</code> on Hits picks a named rhythm, filling Hits and Steps: tresillo, cinquillo, khafif-e-ramal, aksak, Venda, bembé, samba or bossa nova.</td></tr><tr><td>Steps</td><td>Over how many steps, from 1 to 32, a bar of sixteenths unless set.</td></tr><tr><td>Rotate</td><td>Moves the rhythm that many steps later.</td></tr><tr><td>Step</td><td>How long each step lasts: <code>(pattern)</code>, the clip&#39;s pattern&#39;s step size, or a time from the list every time setting shares.</td></tr><tr><td>Restart</td><td>On the generator, when it starts over, as <a href="./../GENERATORS#restart">Generators</a> describes; with &quot;whole song&quot; the rhythm keeps drifting against the bar.</td></tr></tbody></table><p>The rhythm repeats every Steps times Step from the clip&#39;s start, so a rhythm of twelve steps against a bar of sixteen drifts against the bar and lines up again only every three bars. The Euclid editor draws the rhythm under its fields.</p><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Set Euclid on a track, or add a Euclid generator to a chain, as <code>euclid: name</code>, and give clips that chain. <code>examples/other/euclidean.yml</code> is an Afro-Latin percussion piece built this way.</p>',9)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
